size_t fn_05(const uint8_t *input, size_t len, uint8_t *key, uint8_t *output, size_t keylen) {
  if (len < 24 || keylen < 8) {
    return -1;
  }

  uint32_t v0 = (input[0] << 24) | (input[1] << 16) | (input[2] << 8) | input[3];
  uint32_t v1 = (input[4] << 24) | (input[5] << 16) | (input[6] << 8) | input[7];
  uint32_t sum = 0, i;
  uint32_t k0 = (key[0] << 24) | (key[1] << 16) | (key[2] << 8) | key[3];
  uint32_t k1 = (key[4] << 24) | (key[5] << 16) | (key[6] << 8) | key[7];

  uint32_t delta = 0x9e3779b9;
  uint32_t kk0 = k0;
  uint32_t kk1 = k1;

  for (i = 0; i < 32; i++) {
    sum += delta;
    v0 += ((v1 << 4) + kk0) ^ (v1 + sum) ^ ((v1 >> 5) + kk1);
    v1 += ((v0 << 4) + kk1) ^ (v0 + sum) ^ ((v0 >> 5) + kk0);
  }

  output[0] = (uint8_t)(v0 >> 24);
  output[1] = (uint8_t)(v0 >> 16);
  output[2] = (uint8_t)(v0 >> 8);
  output[3] = (uint8_t)(v0);
  output[4] = (uint8_t)(v1 >> 24);
  output[5] = (uint8_t)(v1 >> 16);
  output[6] = (uint8_t)(v1 >> 8);
  output[7] = (uint8_t)(v1);

  return 8;
}
